//! Golden parity tests for the finite-difference kernels (issue #7663).
//!
//! Compares `upstream_pinocchio_id::finite_diff` against vectors generated by
//! the Python source-of-truth scheme in
//! `motion_pipeline/matching/inverse_dyn_pinocchio.py` (`_finite_difference`).
//!
//! Regenerate the goldens with:
//!     python3 tests/generate_parity_finite_diff.py
//! (NumPy only). The generator documents the exact non-uniform-dt scheme.

use std::fs;
use std::path::PathBuf;

use ndarray::Array2;
use upstream_pinocchio_id::finite_diff::{finite_diff_qddot, finite_diff_qdot};

const TOL: f64 = 1e-9;

fn fixture() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("parity_finite_diff.csv")
}

struct Case {
    name: String,
    times: Vec<f64>,
    q: Array2<f64>,
    qdot: Array2<f64>,
    qddot: Array2<f64>,
}

fn load_cases() -> Vec<Case> {
    let text = fs::read_to_string(fixture()).expect("read parity_finite_diff.csv");
    let mut cases = Vec::new();
    for line in text.lines().skip(1).filter(|l| !l.trim().is_empty()) {
        let mut it = line.split(',');
        let name = it.next().unwrap().to_string();
        let n: usize = it.next().unwrap().trim().parse().unwrap();
        let d: usize = it.next().unwrap().trim().parse().unwrap();
        let data: Vec<f64> = it.map(|s| s.trim().parse::<f64>().unwrap()).collect();
        assert_eq!(data.len(), n + 3 * n * d, "row width for case {name}");
        let times = data[..n].to_vec();
        let take =
            |off: usize| Array2::from_shape_vec((n, d), data[off..off + n * d].to_vec()).unwrap();
        let q = take(n);
        let qdot = take(n + n * d);
        let qddot = take(n + 2 * n * d);
        cases.push(Case {
            name,
            times,
            q,
            qdot,
            qddot,
        });
    }
    assert!(!cases.is_empty(), "parity fixture must not be empty");
    cases
}

fn max_abs_diff(a: &Array2<f64>, b: &Array2<f64>) -> f64 {
    a.iter()
        .zip(b.iter())
        .map(|(x, y)| (x - y).abs())
        .fold(0.0_f64, f64::max)
}

#[test]
fn qdot_matches_python_golden() {
    for c in load_cases() {
        let times = ndarray::Array1::from(c.times.clone());
        let got = finite_diff_qdot(c.q.view(), times.view()).unwrap();
        let diff = max_abs_diff(&got, &c.qdot);
        assert!(diff <= TOL, "qdot case {} diff {diff} > {TOL}", c.name);
    }
}

#[test]
fn qddot_matches_python_golden() {
    for c in load_cases() {
        let times = ndarray::Array1::from(c.times.clone());
        let got = finite_diff_qddot(c.q.view(), times.view()).unwrap();
        let diff = max_abs_diff(&got, &c.qddot);
        assert!(diff <= TOL, "qddot case {} diff {diff} > {TOL}", c.name);
    }
}
